// Recherche dans la base de connaissances de Nova Services.
// Entrée : « query » (la question ou des mots-clés). Sortie : les 4 extraits les plus proches.
const BASE = [{"source":"Questions fréquentes","titre":"Comment obtenir un devis ?","texte":"Demandez à être rappelé par un conseiller ou déposez une demande sur le formulaire en ligne. Un conseiller échange avec vous, puis le devis gratuit arrive sous 3 jours ouvrés."},{"source":"Questions fréquentes","titre":"Quels moyens de paiement acceptez-vous ?","texte":"Virement bancaire et prélèvement automatique (pour la maintenance mensuelle). Pas de paiement par chèque ni en espèces."},{"source":"Questions fréquentes","titre":"Quand dois-je payer ?","texte":"Pour un site : 30 % à la signature du devis, le reste à la mise en ligne. La maintenance est prélevée le 5 de chaque mois. Les factures sont payables à 30 jours."},{"source":"Questions fréquentes","titre":"Où trouver mes factures ?","texte":"Les factures sont envoyées par email à l'adresse de facturation du client. Pour obtenir une copie, faites une demande en précisant le mois concerné."},{"source":"Questions fréquentes","titre":"Puis-je résilier ma maintenance ?","texte":"Oui, sans frais, avec un mois de préavis. La demande se fait par écrit (formulaire ou email)."},{"source":"Questions fréquentes","titre":"Le site m'appartient-il ?","texte":"Oui. Le contenu et le nom de domaine appartiennent au client. En cas de départ, Nova Services remet une copie complète du site."},{"source":"Questions fréquentes","titre":"Intervenez-vous sur place ?","texte":"Non. Toutes les interventions se font à distance."},{"source":"Questions fréquentes","titre":"Travaillez-vous avec les particuliers ?","texte":"Non. Nova Services travaille uniquement avec des professionnels et des associations."},{"source":"Horaires et contact","titre":"Horaires d'ouverture","texte":"L'équipe répond du lundi au vendredi, de 9 h à 18 h (heure de Paris), sans interruption à midi. Fermé le samedi, le dimanche et les jours fériés."},{"source":"Horaires et contact","titre":"Fermetures annuelles","texte":"Fermeture entre Noël et le jour de l'An. Pendant cette période, seules les urgences des clients sous contrat de maintenance sont traitées."},{"source":"Horaires et contact","titre":"Délais de réponse","texte":"Une demande reçue un jour ouvré reçoit une première réponse sous 1 jour ouvré. Pour les clients sous contrat de maintenance, une panne bloquante est prise en charge sous 4 heures ouvrées."},{"source":"Horaires et contact","titre":"Comment contacter Nova Services","texte":"Par le formulaire de demande en ligne, par email à contact@nova-services.example, ou en demandant à être rappelé. Le standard téléphonique n'existe pas : un conseiller rappelle sur demande, aux heures d'ouverture."},{"source":"Horaires et contact","titre":"Urgences en dehors des horaires","texte":"En dehors des horaires, aucune personne n'est joignable. Les demandes sont lues le jour ouvré suivant à 9 h."},{"source":"Informations destinées aux clients","titre":"Démarrage d'un projet de site","texte":"Après la signature du devis, un rendez-vous de lancement est fixé dans les 10 jours ouvrés. Le client fournit ses textes, son logo et ses photos. Un interlocuteur unique suit le projet du début à la fin."},{"source":"Informations destinées aux clients","titre":"Sauvegardes","texte":"Les sites en maintenance sont sauvegardés chaque nuit. Les sauvegardes sont gardées 30 jours. Une restauration peut être demandée à tout moment."},{"source":"Informations destinées aux clients","titre":"Sécurité des comptes","texte":"Nova Services ne demande jamais un mot de passe, un code reçu par SMS ou des coordonnées bancaires par email, chat ou téléphone. En cas de doute sur un message, contactez Nova Services avant de répondre."},{"source":"Informations destinées aux clients","titre":"Protection des données","texte":"Les données des clients sont hébergées en Europe. Elles servent uniquement à traiter les demandes et les contrats. Elles ne sont ni vendues ni partagées à des fins commerciales."},{"source":"Procédures simples","titre":"Mot de passe oublié de la messagerie","texte":"Sur la page de connexion de la messagerie, cliquez sur « Mot de passe oublié » et suivez le lien reçu sur l'adresse de secours. Si aucune adresse de secours n'est enregistrée, un conseiller doit réinitialiser le compte : demandez à être rappelé. Nova Services ne demande jamais un mot de passe par email ou par téléphone."},{"source":"Procédures simples","titre":"Signaler une panne du site","texte":"Indiquez l'adresse du site, ce qui ne fonctionne pas et depuis quand. Pour un client sous contrat de maintenance, une panne bloquante est prise en charge sous 4 heures ouvrées."},{"source":"Procédures simples","titre":"Demander une modification du site","texte":"Décrivez la modification souhaitée (page concernée, texte ou image à changer). Les petites modifications sont comprises dans la maintenance, dans la limite de 2 heures par mois."},{"source":"Procédures simples","titre":"Changer les coordonnées de facturation","texte":"Envoyez la nouvelle adresse de facturation et, si besoin, le nouveau nom de la société. Le changement s'applique à la facture suivante."},{"source":"Procédures simples","titre":"Faire effacer ses données personnelles","texte":"Écrivez à contact@nova-services.example en indiquant l'adresse email concernée. Les données sont effacées sous 1 mois, comme le prévoit le RGPD."},{"source":"Procédures simples","titre":"Être rappelé par un conseiller","texte":"Donnez votre nom, votre email, un numéro de téléphone si vous le souhaitez, et l'objet de votre demande. Un conseiller rappelle aux heures d'ouverture, en général sous 1 jour ouvré."},{"source":"Présentation des services","titre":"Qui est Nova Services","texte":"Nova Services accompagne les professionnels (TPE, PME, indépendants, associations) dans leurs projets numériques. L'équipe compte 12 personnes et travaille à distance avec des clients partout en France."},{"source":"Présentation des services","titre":"Création de site internet","texte":"Conception de sites vitrines et de petits sites de vente en ligne : maquette, rédaction des pages avec le client, mise en ligne, formation d'une heure à la mise à jour du site. Délai habituel : 4 à 6 semaines."},{"source":"Présentation des services","titre":"Maintenance et hébergement","texte":"Nova Services héberge le site, fait les mises à jour de sécurité, une sauvegarde chaque nuit et surveille la disponibilité. Les petites modifications de contenu sont comprises dans la limite de 2 heures par mois."},{"source":"Présentation des services","titre":"Support informatique","texte":"Aide à distance pour les postes de travail, la messagerie professionnelle, les comptes et les mots de passe, les imprimantes et le réseau du bureau. Pas d'intervention sur place."},{"source":"Présentation des services","titre":"Automatisation et outils","texte":"Mise en place d'outils simples pour gagner du temps : formulaires, tableaux partagés, envoi automatique d'emails, prise de rendez-vous en ligne, connexion entre outils."},{"source":"Présentation des services","titre":"Ce que Nova Services ne fait pas","texte":"Pas de conseil juridique, comptable ou fiscal. Pas de vente de matériel informatique. Pas de développement d'applications mobiles. Pas de référencement payant (publicité en ligne)."},{"source":"Tarifs","titre":"Site vitrine","texte":"À partir de 1 500 € HT pour un site de 5 pages maximum. Chaque page supplémentaire : 150 € HT."},{"source":"Tarifs","titre":"Petit site de vente en ligne","texte":"À partir de 3 500 € HT, jusqu'à 50 produits."},{"source":"Tarifs","titre":"Maintenance et hébergement","texte":"Abonnement mensuel : 49 € HT par mois pour la maintenance et l'hébergement d'un site, sans engagement de durée, résiliable avec un mois de préavis."},{"source":"Tarifs","titre":"Support informatique","texte":"Forfait de 5 heures : 300 € HT, valable 12 mois. Intervention ponctuelle sans forfait : 75 € HT de l'heure, facturée par tranche de 30 minutes."},{"source":"Tarifs","titre":"Automatisation","texte":"Sur devis, après un premier échange gratuit de 30 minutes."},{"source":"Tarifs","titre":"Devis","texte":"Le devis est gratuit et envoyé sous 3 jours ouvrés après l'échange avec un conseiller. Il reste valable 30 jours."},{"source":"Tarifs","titre":"Remises","texte":"Remise de 10 % pour les associations. Pas d'autre remise prévue."}];

const MOTS_VIDES = new Set('a au aux avec ce ces cet cette comment dans de des du elle en est et etre il ils je la le les leur lui ma mais me mes moi mon ne nous on ou par pas pour qu que quel quelle quels quelles qui sa se ses si son sur ta te tes toi ton tu un une vos votre vous y avez ai suis faire fait peut puis peux veux voudrais bonjour merci svp'.split(' '));
const SYNONYMES = {
  prix: 'tarif', cout: 'tarif', coute: 'tarif', combien: 'tarif', cher: 'tarif', payer: 'paiement', paye: 'paiement',
  reglement: 'paiement', regler: 'paiement', carte: 'paiement', cheque: 'paiement', horaire: 'horaires', heure: 'horaires',
  ouvert: 'ouverture', ouvre: 'ouverture', ferme: 'fermeture', joindre: 'contact', contacter: 'contact', telephone: 'rappel',
  appeler: 'rappel', rappeler: 'rappel', rappelle: 'rappel', conseiller: 'rappel', humain: 'rappel', panne: 'panne',
  bug: 'panne', marche: 'panne', fonctionne: 'panne', plante: 'panne', mdp: 'passe', identifiant: 'passe',
  resilier: 'resilier', resiliation: 'resilier', arreter: 'resilier', abonnement: 'maintenance', mensuel: 'maintenance',
  web: 'site', internet: 'site', boutique: 'vente', ecommerce: 'vente', remise: 'remises', reduction: 'remises',
  promo: 'remises', rgpd: 'personnelles', effacer: 'effacees', supprimer: 'effacees', facturation: 'facture',
};
const normaliser = (t) => String(t).toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').replace(/[^a-z0-9 ]/g, ' ');
const racine = (m) => (m.length > 5 ? m.slice(0, 5) : m.replace(/s$/, ''));
const termes = (t) => normaliser(t).split(/\s+/).filter((m) => m.length > 2 && !MOTS_VIDES.has(m));

const motsQuestion = new Set();
for (const m of termes(query)) motsQuestion.add(racine(SYNONYMES[m] ?? m));
if (motsQuestion.size === 0) return 'AUCUN_RESULTAT : la recherche est vide. Demande une précision à la personne.';

// Un mot présent partout (« site ») compte peu ; un mot rare (« maintenance », « tarif ») compte beaucoup.
const index = BASE.map((s) => ({ s, titre: new Set(termes(s.titre + ' ' + s.source).map(racine)), corps: new Set(termes(s.texte).map(racine)) }));
const poids = (m) => {
  const n = index.filter((x) => x.titre.has(m) || x.corps.has(m)).length;
  return n === 0 ? 0 : Math.log(1 + BASE.length / n);
};
const resultats = index.map(({ s, titre, corps }) => {
  let score = 0;
  for (const m of motsQuestion) { if (titre.has(m)) score += 2 * poids(m); else if (corps.has(m)) score += poids(m); }
  return { ...s, score };
}).filter((s) => s.score >= 2.5).sort((a, b) => b.score - a.score).slice(0, 4);

if (resultats.length === 0) {
  return 'AUCUN_RESULTAT : rien sur ce sujet dans les ressources de Nova Services. Ne réponds pas de mémoire : dis que tu n\'as pas l\'information et propose de transmettre à un conseiller.';
}
return resultats.map((s, i) => `[${i + 1}] Source : ${s.source} — ${s.titre}\n${s.texte}`).join('\n\n');

